<?= $this->section('conteudo') ?>
<?php $instrutoresPorId = []; foreach ($instrutores as $item) { $instrutoresPorId[$item['id']] = $item; } $markers = []; foreach ($mapLocais as $local) { $owner = $instrutoresPorId[$local['instrutor_id']] ?? []; $markers[] = ['lat' => (float) $local['latitude'], 'lng' => (float) $local['longitude'], 'local' => $local['nome'], 'apelido' => $owner['apelido'] ?? '', 'distancia' => $local['distancia'] ?? null, 'url' => base_url('aulas-e-locais/' . ($owner['id'] ?? ''))]; } ?>
<section class="aulas-hero"><div class="container"><span class="aulas-rank">Capoeira perto de você</span><h1>Aulas e locais</h1><p>Encontre quem ministra aulas, conheça suas trajetórias e veja no mapa onde acontecem os encontros.</p><form class="aulas-locator" action="<?= base_url('aulas-e-locais') ?>" method="get"><label class="visually-hidden" for="cep">Seu CEP</label><input id="cep" name="cep" inputmode="numeric" maxlength="9" value="<?= esc($cep, 'attr') ?>" placeholder="Informe seu CEP"><button type="submit">Encontrar próximas</button></form><?php if ($searchError) : ?><p class="aulas-search-error"><?= esc($searchError) ?></p><?php endif ?></div></section>
<section class="container aulas-map-wrap"><div id="aulas-map" class="aulas-map" aria-label="Mapa de locais de aula"></div></section>
<section class="container aulas-section"><div class="d-flex justify-content-between align-items-end gap-3 mb-4"><div><span class="aulas-rank"><?= $origin ? 'Mais perto de ' . esc($cep) : 'Quem ensina' ?></span><h2 class="mt-2 mb-0">Pessoas que ministram aulas</h2></div><span class="text-muted"><?= count($instrutores) ?> cadastro(s)</span></div><div class="row g-4">
<?php foreach ($instrutores as $instrutor) : ?><article class="col-md-6 col-lg-4"><div class="aulas-card"><?php if (!empty($instrutor['foto_perfil'])) : ?><img class="aulas-card__image" src="<?= base_url('uploads/' . $instrutor['foto_perfil']) ?>" alt="<?= esc($instrutor['apelido'], 'attr') ?>"><?php else : ?><div class="aulas-card__placeholder" aria-hidden="true"><?= esc(mb_strtoupper(mb_substr($instrutor['apelido'], 0, 1))) ?></div><?php endif ?><div class="aulas-card__body"><span class="aulas-rank"><?= esc($instrutor['graduacao']) ?></span><h2><a href="<?= base_url('aulas-e-locais/' . $instrutor['id']) ?>"><?= esc($instrutor['apelido']) ?></a></h2><p class="aulas-card__name"><?= esc($instrutor['nome']) ?></p><?php $locais = $locaisPorInstrutor[$instrutor['id']] ?? []; if ($locais) : ?><div class="aulas-card__locations"><?php foreach (array_slice($locais, 0, 2) as $local) : ?><div class="aulas-card__location"><strong><?= esc($local['nome']) ?></strong><?php if (isset($local['distancia'])) : ?><br><span class="aulas-distance"><?= number_format((float) $local['distancia'], 1, ',', '.') ?> km de você</span><?php endif ?><?php if ($local['dias_horarios']) : ?><br><span class="text-muted"><?= esc($local['dias_horarios']) ?></span><?php endif ?></div><?php endforeach ?></div><?php endif ?><a class="aulas-card__link" href="<?= base_url('aulas-e-locais/' . $instrutor['id']) ?>">Ver perfil e locais →</a></div></div></article><?php endforeach ?>
<?php if ($instrutores === []) : ?><p class="text-muted">Ainda não há aulas cadastradas.</p><?php endif ?></div></section>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const markers=<?= json_encode($markers, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,origin=<?= json_encode($origin, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char])),map=L.map('aulas-map',{scrollWheelZoom:false});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);const bounds=[];if(origin){L.circleMarker([origin.latitude,origin.longitude],{radius:9,color:'#fff',weight:3,fillColor:'#c96a4a',fillOpacity:1}).addTo(map).bindPopup('Seu CEP');bounds.push([origin.latitude,origin.longitude])}markers.forEach(item=>{const marker=L.marker([item.lat,item.lng]).addTo(map),distance=item.distancia===null?'':'<br>'+String(item.distancia).replace('.',',')+' km de você';marker.bindPopup('<strong>'+escapeHtml(item.local)+'</strong><br>'+escapeHtml(item.apelido)+distance+(item.url?'<br><a href="'+item.url+'">Ver perfil</a>':''));bounds.push([item.lat,item.lng])});if(bounds.length){map.fitBounds(bounds,{padding:[40,40],maxZoom:14})}else{map.setView([-14.235,-51.9253],4)}</script><?= $this->endSection() ?>
